draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20*Math.sin(t), 0, 2*Math.PI);
  ctx.fill();

  // clouds
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 + 100*Math.cos(t), H/2 - 50*Math.sin(t), 20 + 10*Math.sin(2*t), 0, 2*Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 - 150*Math.cos(t), H/2 + 20*Math.sin(t), 30 + 15*Math.sin(3*t), 0, 2*Math.PI);
  ctx.fill();

  // trees
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H - 50);
  ctx.lineTo(W/2 - 100, H - 150 - 50*Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H - 50);
  ctx.lineTo(W/2 + 50, H - 120 - 30*Math.sin(2*t));
  ctx.stroke();

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H - 100, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 80);
  ctx.lineTo(W/2, H - 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 60);
  ctx.lineTo(W/2 - 20, H - 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H - 60);
  ctx.lineTo(W/2 + 20, H - 80);
  ctx.stroke();

  ctx.restore();
}
